// Generated by tools/bundle-rules.mjs from rules/calculus.yaml and rules/cas/. Edit those, then npm run build:rules.
export const DEFAULT_RULES = [
  // rules/calculus.yaml
  "name: Differentiation\n\n# `u v der` means d(u)/dv (MathZetta's postfix: mathzetta/docs/postfix.md). Every rule here rewrites one derivative into smaller\n# derivatives, so differentiating always terminates: the expressions sitting\n# under a `D` get strictly smaller at every step.\n#\n# The variable is a slot, not a fixed letter, so these rules work for d/dx,\n# d/dt or anything else. That is what freeOf and dependsOn are for: they ask\n# whether one operand mentions whatever the variable slot bound to.\n#\n# Where two rules share a structure key, requirements keep them apart and\n# priority picks the one that reads better. The constant-multiple rule outranks\n# the product rule for exactly that reason.\n\nrules:\n  # ---- the two base cases ----------------------------------------------\n  - id: d-constant\n    name: Derivative of a constant\n    mode: differentiate\n    pattern: c v der\n    require:\n      - [freeOf, c, v]\n    output: \"0\"\n    priority: 10\n    explain: \"{c} does not change when {v} changes, so its rate of change is 0.\"\n    tags: [base]\n\n  - id: d-variable\n    name: Derivative of the variable\n    mode: differentiate\n    pattern: u v der\n    require:\n      - [sameAs, u, v]\n    output: \"1\"\n    priority: 10\n    explain: \"{v} changes exactly as fast as itself, so the rate is 1.\"\n    tags: [base]\n\n  # ---- splitting a derivative into smaller ones ------------------------\n  - id: d-sum\n    name: Sum rule\n    mode: differentiate\n    pattern: u w + v der\n    output: u v der w v der +\n    explain: \"Differentiate {u} and {w} separately, then add the two results.\"\n    tags: [split]\n\n  - id: d-difference\n    name: Difference rule\n    mode: differentiate\n    pattern: u w - v der\n    output: u v der w v der -\n    explain: \"Differentiate {u} and {w} separately, then subtract the second from the first.\"\n    tags: [split]\n\n  - id: d-negate\n    name: Derivative of a negative\n    mode: differentiate\n    pattern: u neg v der\n    output: u v der neg\n    explain: \"The minus sign just carries through to the derivative of {u}.\"\n    tags: [split]\n\n  - id: d-constant-multiple\n    name: Constant multiple rule\n    mode: differentiate\n    pattern: c u * v der\n    commutative: true\n    require:\n      - [freeOf, c, v]\n      - [dependsOn, u, v]\n    output: c u v der *\n    priority: 5\n    explain: \"{c} is only a scale factor, so it comes along unchanged while {u} is differentiated.\"\n    tags: [split]\n\n  - id: d-constant-divisor\n    name: Dividing by a constant\n    mode: differentiate\n    pattern: u c / v der\n    require:\n      - [freeOf, c, v]\n    output: u v der c /\n    priority: 5\n    explain: \"Dividing by {c} is only a scale factor, so differentiate {u} and keep the division.\"\n    tags: [split]\n\n  - id: d-product\n    name: Product rule\n    mode: differentiate\n    pattern: u w * v der\n    require:\n      - [dependsOn, u, v]\n      - [dependsOn, w, v]\n    output: u v der w * u w v der * +\n    explain: \"Differentiate {u} and keep {w}, then keep {u} and differentiate {w}, and add the two.\"\n    tags: [split]\n\n  - id: d-quotient\n    name: Quotient rule\n    mode: differentiate\n    pattern: u w / v der\n    output: u v der w * u w v der * - w 2 ^ /\n    explain: \"Bottom times the derivative of the top, minus top times the derivative of the bottom, all over {w} squared.\"\n    tags: [split]\n\n  # ---- powers -----------------------------------------------------------\n  - id: d-power-of-variable\n    name: Power rule\n    mode: differentiate\n    pattern: u n ^ v der\n    require:\n      - [sameAs, u, v]\n      - [freeOf, n, v]\n    output: n u n 1 - ^ *\n    fold: true\n    priority: 6\n    explain: \"Bring the {n} down in front and drop the power by one.\"\n    tags: [power]\n\n  - id: d-power-chain\n    name: Power rule with the chain rule\n    mode: differentiate\n    pattern: u n ^ v der\n    require:\n      - [freeOf, n, v]\n      - [dependsOn, u, v]\n    output: n u n 1 - ^ * u v der *\n    fold: true\n    explain: \"Bring the {n} down and drop the power by one, then multiply by the derivative of {u}.\"\n    tags: [power, chain]\n\n  - id: d-exponential-base\n    name: Derivative of a constant to a power\n    mode: differentiate\n    pattern: a u ^ v der\n    require:\n      - [freeOf, a, v]\n      - [dependsOn, u, v]\n    output: a u ^ a ln * u v der *\n    explain: \"A constant base gives itself back, multiplied by the natural log of {a} and the derivative of {u}.\"\n    tags: [power, chain]\n\n  # ---- the standard functions, each with its chain-rule factor ---------\n  # e^u is `=e u ^`: the base is the literal symbol e. Outranks the general\n  # a^u rule (which would give e^u · ln e · u').\n  - id: d-exp\n    name: Derivative of e to a power\n    mode: differentiate\n    pattern: =e u ^ v der\n    require:\n      - [dependsOn, u, v]\n    output: =e u ^ u v der *\n    priority: 7\n    explain: \"e to a power is its own derivative, times the derivative of {u}.\"\n    tags: [chain]\n\n  - id: d-ln\n    name: Derivative of a natural log\n    mode: differentiate\n    pattern: u ln v der\n    output: u v der u /\n    explain: \"The derivative of {u} over {u} itself.\"\n    tags: [chain]\n\n  - id: d-sqrt\n    name: Derivative of a square root\n    mode: differentiate\n    pattern: u sqrt v der\n    output: u v der 2 u sqrt * /\n    explain: \"The derivative of {u}, over twice the square root of {u}.\"\n    tags: [chain]\n\n  - id: d-sin\n    name: Derivative of sine\n    mode: differentiate\n    pattern: u sin v der\n    output: u cos u v der *\n    explain: \"Sine differentiates to cosine, times the derivative of {u}.\"\n    tags: [chain, trig]\n\n  - id: d-cos\n    name: Derivative of cosine\n    mode: differentiate\n    pattern: u cos v der\n    output: u sin u v der * neg\n    explain: \"Cosine differentiates to minus sine, times the derivative of {u}.\"\n    tags: [chain, trig]\n\n  - id: d-tan\n    name: Derivative of tangent\n    mode: differentiate\n    pattern: u tan v der\n    output: u v der u cos 2 ^ /\n    explain: \"The derivative of {u}, over cosine squared of {u}.\"\n    tags: [chain, trig]\n\n  # ---- the rest of the standard functions -----------------------------\n  - id: d-csc\n    name: Derivative of cosecant\n    mode: differentiate\n    pattern: u csc v der\n    output: u csc u cot * u v der * neg\n    explain: \"Cosecant differentiates to minus cosecant times cotangent, times the derivative of {u}.\"\n    tags: [chain, trig]\n\n  - id: d-sec\n    name: Derivative of secant\n    mode: differentiate\n    pattern: u sec v der\n    output: u sec u tan * u v der *\n    explain: \"Secant differentiates to secant times tangent, times the derivative of {u}.\"\n    tags: [chain, trig]\n\n  - id: d-cot\n    name: Derivative of cotangent\n    mode: differentiate\n    pattern: u cot v der\n    output: u v der u sin 2 ^ / neg\n    explain: \"Minus the derivative of {u}, over sine squared of {u}.\"\n    tags: [chain, trig]\n\n  - id: d-arcsin\n    name: Derivative of arcsine\n    mode: differentiate\n    pattern: u arcsin v der\n    output: u v der 1 u 2 ^ - sqrt /\n    explain: \"The derivative of {u}, over the square root of 1 minus {u} squared.\"\n    tags: [chain, trig]\n\n  - id: d-arccos\n    name: Derivative of arccosine\n    mode: differentiate\n    pattern: u arccos v der\n    output: u v der 1 u 2 ^ - sqrt / neg\n    explain: \"Minus the derivative of {u}, over the square root of 1 minus {u} squared.\"\n    tags: [chain, trig]\n\n  - id: d-arctan\n    name: Derivative of arctangent\n    mode: differentiate\n    pattern: u arctan v der\n    output: u v der 1 u 2 ^ + /\n    explain: \"The derivative of {u}, over 1 plus {u} squared.\"\n    tags: [chain, trig]\n\n  - id: d-sinh\n    name: Derivative of hyperbolic sine\n    mode: differentiate\n    pattern: u sinh v der\n    output: u cosh u v der *\n    explain: \"Hyperbolic sine differentiates to hyperbolic cosine, times the derivative of {u}.\"\n    tags: [chain, hyperbolic]\n\n  - id: d-cosh\n    name: Derivative of hyperbolic cosine\n    mode: differentiate\n    pattern: u cosh v der\n    output: u sinh u v der *\n    explain: \"Hyperbolic cosine differentiates to hyperbolic sine — no minus sign, unlike cosine — times the derivative of {u}.\"\n    tags: [chain, hyperbolic]\n\n  - id: d-tanh\n    name: Derivative of hyperbolic tangent\n    mode: differentiate\n    pattern: u tanh v der\n    output: u v der u cosh 2 ^ /\n    explain: \"The derivative of {u}, over hyperbolic cosine squared of {u}.\"\n    tags: [chain, hyperbolic]\n\n  - id: d-arcsinh\n    name: Derivative of inverse hyperbolic sine\n    mode: differentiate\n    pattern: u arcsinh v der\n    output: u v der u 2 ^ 1 + sqrt /\n    explain: \"The derivative of {u}, over the square root of {u} squared plus 1.\"\n    tags: [chain, hyperbolic]\n\n  - id: d-arccosh\n    name: Derivative of inverse hyperbolic cosine\n    mode: differentiate\n    pattern: u arccosh v der\n    output: u v der u 2 ^ 1 - sqrt /\n    explain: \"The derivative of {u}, over the square root of {u} squared minus 1.\"\n    tags: [chain, hyperbolic]\n\n  - id: d-arctanh\n    name: Derivative of inverse hyperbolic tangent\n    mode: differentiate\n    pattern: u arctanh v der\n    output: u v der 1 u 2 ^ - /\n    explain: \"The derivative of {u}, over 1 minus {u} squared.\"\n    tags: [chain, hyperbolic]\n\n  # log base a: `a u log` in MathZetta's postfix\n  - id: d-log\n    name: Derivative of a logarithm\n    mode: differentiate\n    pattern: a u log v der\n    require:\n      - [freeOf, a, v]\n    output: u v der u a ln * /\n    explain: \"The derivative of {u}, over {u} times the natural log of {a}.\"\n    tags: [chain]\n\n  - id: d-abs\n    name: Derivative of an absolute value\n    mode: differentiate\n    pattern: u abs v der\n    output: u u abs / u v der *\n    explain: \"The absolute value keeps the sign of {u}: {u} over its absolute value, times the derivative of {u}.\"\n    tags: [chain]\n\n  # n-th root: `n u root`\n  - id: d-root\n    name: Derivative of a root\n    mode: differentiate\n    pattern: n u root v der\n    require:\n      - [freeOf, n, v]\n    output: u v der n n u root n 1 - ^ * /\n    fold: true\n    explain: \"The derivative of {u}, over {n} times the {n}th root of {u} to the power {n} minus 1.\"\n    tags: [chain]\n",
  // rules/cas/derivatives.yaml
  "name: More derivatives\n\n# Derivative rules the CAS adds to rules/calculus.yaml (which calcvidnew also uses).\n\nrules:\n  - id: d-general-power\n    name: A power with the variable in both places\n    mode: differentiate\n    pattern: u w ^ v der\n    require:\n      - [dependsOn, u, v]\n      - [dependsOn, w, v]\n    output: u w ^ w v der u ln * w u v der * u / + *\n    explain: \"Write {u}^{w} as e^({w} ln {u}) and use the chain rule: the derivative is {u}^{w} times the derivative of {w} ln {u}.\"\n    tags: [chain]\n",
  // rules/cas/integrals.yaml
  "name: Integrals\n\n# mode: integrate. `f v 2 int` is ∫ f dv (MathZetta's postfix; the 2 counts f and v).\n# Each rule turns one integral into smaller ones, or into an answer. The CAS also\n# tries, when no rule fits: multiplying out, a linear substitution (∫ f(ax + b) dx\n# from the rule for ∫ f(u) du), and integration by parts for polynomial × e^, sin,\n# cos, ln, arctan. Definite integrals are the antiderivative between the limits.\n#\n# Patterns see the normal form: 1/x is \"1 x /\", x^-2 is \"1 x 2 ^ /\", √x is \"x sqrt\",\n# 1/√(1 - x²) is \"1 x 2 ^ neg 1 + sqrt /\".\n\nrules:\n  # ---- splitting -----------------------------------------------------------\n  - id: i-sum\n    name: Sum rule\n    mode: integrate\n    pattern: u w + v 2 int\n    output: u v 2 int w v 2 int +\n    explain: \"Integrate {u} and {w} separately, and add.\"\n    tags: [split]\n\n  - id: i-difference\n    name: Difference rule\n    mode: integrate\n    pattern: u w - v 2 int\n    output: u v 2 int w v 2 int -\n    explain: \"Integrate {u} and {w} separately, and subtract.\"\n    tags: [split]\n\n  - id: i-negate\n    name: A minus sign\n    mode: integrate\n    pattern: u neg v 2 int\n    output: u v 2 int neg\n    explain: \"The minus sign comes out of the integral.\"\n    tags: [split]\n\n  - id: i-constant-multiple\n    name: Constant multiple\n    mode: integrate\n    pattern: c u * v 2 int\n    commutative: true\n    require:\n      - [freeOf, c, v]\n      - [dependsOn, u, v]\n    output: c u v 2 int *\n    priority: 5\n    explain: \"{c} doesn't change with {v}, so it comes out of the integral.\"\n    tags: [split]\n\n  - id: i-constant-divisor\n    name: Dividing by a constant\n    mode: integrate\n    pattern: u c / v 2 int\n    require:\n      - [freeOf, c, v]\n      - [dependsOn, u, v]\n    output: u v 2 int c /\n    priority: 5\n    explain: \"Dividing by {c} comes out of the integral.\"\n    tags: [split]\n\n  - id: i-constant-over\n    name: A constant over something\n    mode: integrate\n    pattern: c u / v 2 int\n    require:\n      - [freeOf, c, v]\n      - [dependsOn, u, v]\n    when:\n      c: [notOne]\n    output: c 1 u / v 2 int *\n    priority: 4\n    explain: \"{c} comes out of the integral, leaving ∫ 1/{u}.\"\n    tags: [split]\n\n  # ---- the table -----------------------------------------------------------\n  - id: i-constant\n    name: Integral of a constant\n    mode: integrate\n    pattern: c v 2 int\n    require:\n      - [freeOf, c, v]\n    output: c v *\n    priority: 10\n    explain: \"A constant {c} integrates to {c}·{v}.\"\n    tags: [base]\n\n  - id: i-variable\n    name: Integral of the variable\n    mode: integrate\n    pattern: u v 2 int\n    require:\n      - [sameAs, u, v]\n    output: v 2 ^ 2 /\n    priority: 10\n    explain: \"∫ {v} d{v} = {v}²/2.\"\n    tags: [base]\n\n  - id: i-power\n    name: Power rule\n    mode: integrate\n    pattern: u n ^ v 2 int\n    require:\n      - [sameAs, u, v]\n      - [freeOf, n, v]\n    when:\n      n: [notMinusOne]\n    output: v n 1 + ^ n 1 + /\n    explain: \"Add 1 to the power and divide by the new power: {result}.\"\n    tags: [power]\n\n  - id: i-reciprocal\n    name: Integral of 1/x\n    mode: integrate\n    pattern: 1 u / v 2 int\n    require:\n      - [sameAs, u, v]\n    output: v abs ln\n    explain: \"∫ 1/{v} d{v} = ln|{v}| (the power rule can't divide by 0 here).\"\n    tags: [log]\n\n  - id: i-reciprocal-power\n    name: Power rule (a power below)\n    mode: integrate\n    pattern: 1 u n ^ / v 2 int\n    require:\n      - [sameAs, u, v]\n      - [freeOf, n, v]\n    when:\n      n: [notOne]\n    output: v 1 n - ^ 1 n - /\n    explain: \"1/{v}^{n} is {v}^(-{n}): add 1 to the power and divide by it.\"\n    tags: [power]\n\n  - id: i-sqrt\n    name: Integral of a square root\n    mode: integrate\n    pattern: u sqrt v 2 int\n    require:\n      - [sameAs, u, v]\n    output: 2 v 3 2 / ^ * 3 /\n    explain: \"√{v} is {v}^(1/2): add 1 to the power and divide by 3/2.\"\n    tags: [power]\n\n  - id: i-reciprocal-sqrt\n    name: Integral of 1/√x\n    mode: integrate\n    pattern: 1 u sqrt / v 2 int\n    require:\n      - [sameAs, u, v]\n    output: 2 v sqrt *\n    explain: \"1/√{v} is {v}^(-1/2): add 1 to the power and divide by 1/2.\"\n    tags: [power]\n\n  - id: i-root\n    name: Integral of a root\n    mode: integrate\n    pattern: n u root v 2 int\n    require:\n      - [sameAs, u, v]\n      - [freeOf, n, v]\n    output: v 1 n / 1 + ^ 1 n / 1 + /\n    explain: \"The {n}th root of {v} is {v}^(1/{n}): add 1 to the power and divide by it.\"\n    tags: [power]\n\n  - id: i-exp\n    name: Integral of e^x\n    mode: integrate\n    pattern: =e u ^ v 2 int\n    require:\n      - [sameAs, u, v]\n    output: =e v ^\n    explain: \"e^{v} is its own integral.\"\n    tags: [exp]\n\n  - id: i-exponential\n    name: Integral of a^x\n    mode: integrate\n    pattern: a u ^ v 2 int\n    require:\n      - [sameAs, u, v]\n      - [freeOf, a, v]\n    output: a v ^ a ln /\n    explain: \"∫ {a}^{v} d{v} = {a}^{v} / ln {a}.\"\n    tags: [exp]\n\n  - id: i-ln\n    name: Integral of ln x\n    mode: integrate\n    pattern: u ln v 2 int\n    require:\n      - [sameAs, u, v]\n    output: v v ln * v -\n    explain: \"By parts: ∫ ln {v} d{v} = {v} ln {v} - {v}.\"\n    tags: [log]\n\n  - { id: i-sin, name: Integral of sin, mode: integrate, pattern: u sin v 2 int, require: [[sameAs, u, v]], output: v cos neg, tags: [trig], explain: \"The derivative of -cos {v} is sin {v}.\" }\n  - { id: i-cos, name: Integral of cos, mode: integrate, pattern: u cos v 2 int, require: [[sameAs, u, v]], output: v sin, tags: [trig], explain: \"The derivative of sin {v} is cos {v}.\" }\n  - { id: i-tan, name: Integral of tan, mode: integrate, pattern: u tan v 2 int, require: [[sameAs, u, v]], output: v cos abs ln neg, tags: [trig], explain: \"tan = sin/cos, and -ln|cos {v}| differentiates to it.\" }\n  - { id: i-sec-squared, name: Integral of sec², mode: integrate, pattern: 1 u cos 2 ^ / v 2 int, require: [[sameAs, u, v]], output: v tan, tags: [trig], explain: \"The derivative of tan {v} is 1/cos²{v}.\" }\n  - { id: i-sec-squared-written, name: Integral of sec², mode: integrate, pattern: u sec 2 ^ v 2 int, require: [[sameAs, u, v]], output: v tan, tags: [trig], explain: \"The derivative of tan {v} is sec²{v}.\" }\n  - { id: i-csc-squared, name: Integral of csc², mode: integrate, pattern: 1 u sin 2 ^ / v 2 int, require: [[sameAs, u, v]], output: v cot neg, tags: [trig], explain: \"The derivative of -cot {v} is 1/sin²{v}.\" }\n  - { id: i-sin-squared, name: Integral of sin², mode: integrate, pattern: u sin 2 ^ v 2 int, require: [[sameAs, u, v]], output: v 2 / 2 v * sin 4 / -, tags: [trig], explain: \"sin²{v} = (1 - cos 2{v})/2, which integrates term by term.\" }\n  - { id: i-cos-squared, name: Integral of cos², mode: integrate, pattern: u cos 2 ^ v 2 int, require: [[sameAs, u, v]], output: v 2 / 2 v * sin 4 / +, tags: [trig], explain: \"cos²{v} = (1 + cos 2{v})/2, which integrates term by term.\" }\n  - { id: i-sinh, name: Integral of sinh, mode: integrate, pattern: u sinh v 2 int, require: [[sameAs, u, v]], output: v cosh, tags: [trig], explain: \"The derivative of cosh {v} is sinh {v}.\" }\n  - { id: i-cosh, name: Integral of cosh, mode: integrate, pattern: u cosh v 2 int, require: [[sameAs, u, v]], output: v sinh, tags: [trig], explain: \"The derivative of sinh {v} is cosh {v}.\" }\n  - { id: i-arctan, name: Integral of 1/(1 + x²), mode: integrate, pattern: 1 u 2 ^ 1 + / v 2 int, require: [[sameAs, u, v]], output: v arctan, tags: [trig], explain: \"The derivative of arctan {v} is 1/(1 + {v}²).\" }\n  - { id: i-arcsin, name: Integral of 1/√(1 - x²), mode: integrate, pattern: 1 u 2 ^ neg 1 + sqrt / v 2 int, require: [[sameAs, u, v]], output: v arcsin, tags: [trig], explain: \"The derivative of arcsin {v} is 1/√(1 - {v}²).\" }\n",
  // rules/cas/simplify.yaml
  "name: Values and identities\n\n# The CAS's simplify rules (mode: simplify). They see expressions in normal form\n# (src/cas/form.js), as drawn: x/2, 2x - 3, -x, √x is \"x sqrt\",\n# ∛x is \"3 x root\", π/6 is \"=pi 6 /\", 2π/3 is \"2 =pi * 3 /\", e^x is \"=e x ^\".\n#\n#   - a word is a slot (u, v, n …); a fixed symbol is written =pi, =e\n#   - a number is itself; \"1 2 /\" is ½\n#   - arithmetic (2 + 3, x + x, √8 = 2√2) is done for you before and after every rule\n#   - a rule for a sum or product of two parts also fires on any two parts of a longer one\n#   - tags pick what a step list shows (steps: 'brief' hides value, identity, tidy …)\n#\n# To change one: copy it into a file of your own with the same id and edit it;\n# to turn one off: give its id with enabled: false. createCAS({ rules: [yours] }).\n\nrules:\n  # ---- logs and exponentials -------------------------------------------\n  - id: ln-one\n    name: Log of 1\n    pattern: 1 ln\n    output: \"0\"\n    explain: \"e^0 = 1, so ln 1 = 0.\"\n    tags: [value]\n\n  - id: ln-e\n    name: Log of e\n    pattern: =e ln\n    output: \"1\"\n    explain: \"e^1 = e, so ln e = 1.\"\n    tags: [value]\n\n  - id: ln-exp\n    name: Log undoes e to a power\n    pattern: =e u ^ ln\n    output: u\n    explain: \"ln and e^ undo each other: ln(e^{u}) = {u}.\"\n    tags: [inverse]\n\n  - id: exp-ln\n    name: e to a power undoes the log\n    pattern: =e u ln ^\n    output: u\n    explain: \"e^ and ln undo each other: e^(ln {u}) = {u} (for {u} > 0).\"\n    tags: [inverse]\n\n  - id: exp-multiple-ln\n    name: A multiple of a log in a power\n    pattern: =e n u ln * ^\n    when:\n      n: [isRational]\n    output: u n ^\n    explain: \"e^({n} ln {u}) = (e^(ln {u}))^{n} = {result}.\"\n    tags: [inverse]\n\n  - id: log-same-base\n    name: Log of its own base\n    pattern: b b log\n    output: \"1\"\n    explain: \"{b}^1 = {b}, so the log of {b} to base {b} is 1.\"\n    tags: [value]\n\n  - id: log-of-power\n    name: Log undoes a power of its base\n    pattern: b b u ^ log\n    output: u\n    explain: \"log base {b} and {b}^ undo each other.\"\n    tags: [inverse]\n\n  - id: power-of-log\n    name: A power undoes the log to its base\n    pattern: b b u log ^\n    output: u\n    explain: \"{b}^(log base {b} of {u}) = {u}.\"\n    tags: [inverse]\n\n  # ---- roots and absolute value --------------------------------------------\n  - id: sqrt-of-square\n    name: Square root of a square\n    pattern: u 2 ^ sqrt\n    output: u abs\n    explain: \"√({u}²) is the size of {u}, whatever its sign: |{u}|.\"\n    tags: [identity]\n\n  - id: abs-squared\n    name: Absolute value squared\n    pattern: u abs 2 ^\n    output: u 2 ^\n    explain: \"Squaring removes the sign anyway: |{u}|² = {u}².\"\n    tags: [identity]\n\n  - id: abs-of-abs\n    name: Absolute value twice\n    pattern: u abs abs\n    output: u abs\n    explain: \"|{u}| is never negative, so its absolute value is itself.\"\n    tags: [identity]\n\n  - id: abs-positive\n    name: Absolute value of a positive number\n    pattern: u abs\n    when:\n      u: [isPositiveConstant]\n    output: u\n    explain: \"{u} is positive, so |{u}| = {u}.\"\n    tags: [value]\n\n  - id: abs-negative\n    name: Absolute value of a negative number\n    pattern: u abs\n    when:\n      u: [isNegativeConstant]\n    output: u neg\n    explain: \"{u} is negative, so |{u}| = -({u}).\"\n    tags: [value]\n\n  - id: abs-of-exp\n    name: e to a power is positive\n    pattern: =e u ^ abs\n    output: =e u ^\n    explain: \"e to any power is positive, so the absolute value changes nothing.\"\n    tags: [identity]\n\n  # ---- trigonometry: signs and turns ---------------------------------------\n  - id: sin-odd\n    name: Sine of a negative angle\n    pattern: u sin\n    when:\n      u: [hasMinusSign]\n    output: u neg sin neg\n    explain: \"sin(-θ) = -sin θ.\"\n    tags: [symmetry]\n\n  - id: cos-even\n    name: Cosine of a negative angle\n    pattern: u cos\n    when:\n      u: [hasMinusSign]\n    output: u neg cos\n    explain: \"cos(-θ) = cos θ.\"\n    tags: [symmetry]\n\n  - id: tan-odd\n    name: Tangent of a negative angle\n    pattern: u tan\n    when:\n      u: [hasMinusSign]\n    output: u neg tan neg\n    explain: \"tan(-θ) = -tan θ.\"\n    tags: [symmetry]\n\n  - id: sin-full-turn\n    name: A full turn\n    pattern: u sin\n    when:\n      u: [[piMultipleAtLeast, 2]]\n    output: u 2 =pi * - sin\n    explain: \"Turning a full 2π brings you back: sin({u}) = sin({u} - 2π).\"\n    tags: [symmetry]\n\n  - id: cos-full-turn\n    name: A full turn\n    pattern: u cos\n    when:\n      u: [[piMultipleAtLeast, 2]]\n    output: u 2 =pi * - cos\n    explain: \"Turning a full 2π brings you back: cos({u}) = cos({u} - 2π).\"\n    tags: [symmetry]\n\n  - id: tan-half-turn\n    name: Tangent repeats every π\n    pattern: u tan\n    when:\n      u: [[piMultipleAtLeast, 1]]\n    output: u =pi - tan\n    explain: \"tan repeats every π: tan({u}) = tan({u} - π).\"\n    tags: [symmetry]\n\n  - id: sin-half-turn\n    name: A half turn\n    pattern: u sin\n    when:\n      u: [[piMultipleAbove, 1], [piMultipleBelow, 2]]\n    output: u =pi - sin neg\n    explain: \"Half a turn flips the sign: sin({u}) = -sin({u} - π).\"\n    tags: [symmetry]\n\n  - id: cos-half-turn\n    name: A half turn\n    pattern: u cos\n    when:\n      u: [[piMultipleAbove, 1], [piMultipleBelow, 2]]\n    output: u =pi - cos neg\n    explain: \"Half a turn flips the sign: cos({u}) = -cos({u} - π).\"\n    tags: [symmetry]\n\n  - id: sin-second-quarter\n    name: The second quarter turn\n    pattern: u sin\n    when:\n      u: [[piMultipleAbove, 1/2], [piMultipleAtMost, 1]]\n    output: =pi u - sin\n    explain: \"sin({u}) = sin(π - {u}).\"\n    tags: [symmetry]\n\n  - id: cos-second-quarter\n    name: The second quarter turn\n    pattern: u cos\n    when:\n      u: [[piMultipleAbove, 1/2], [piMultipleAtMost, 1]]\n    output: =pi u - cos neg\n    explain: \"cos({u}) = -cos(π - {u}).\"\n    tags: [symmetry]\n\n  - id: tan-second-quarter\n    name: The second quarter turn\n    pattern: u tan\n    when:\n      u: [[piMultipleAbove, 1/2], [piMultipleBelow, 1]]\n    output: =pi u - tan neg\n    explain: \"tan({u}) = -tan(π - {u}).\"\n    tags: [symmetry]\n\n  # ---- trigonometry: the standard angles -------------------------------------\n  - { id: sin-0, name: Sine of 0, pattern: 0 sin, output: \"0\", tags: [value], explain: \"sin 0 = 0.\" }\n  - { id: sin-pi-6, name: Sine of π/6, pattern: =pi 6 / sin, output: 1 2 /, tags: [value], explain: \"sin(π/6) = 1/2.\" }\n  - { id: sin-pi-4, name: Sine of π/4, pattern: =pi 4 / sin, output: 2 sqrt 2 /, tags: [value], explain: \"sin(π/4) = √2/2.\" }\n  - { id: sin-pi-3, name: Sine of π/3, pattern: =pi 3 / sin, output: 3 sqrt 2 /, tags: [value], explain: \"sin(π/3) = √3/2.\" }\n  - { id: sin-pi-2, name: Sine of π/2, pattern: =pi 2 / sin, output: \"1\", tags: [value], explain: \"sin(π/2) = 1.\" }\n  - { id: sin-pi, name: Sine of π, pattern: =pi sin, output: \"0\", tags: [value], explain: \"sin π = 0.\" }\n  - { id: cos-0, name: Cosine of 0, pattern: 0 cos, output: \"1\", tags: [value], explain: \"cos 0 = 1.\" }\n  - { id: cos-pi-6, name: Cosine of π/6, pattern: =pi 6 / cos, output: 3 sqrt 2 /, tags: [value], explain: \"cos(π/6) = √3/2.\" }\n  - { id: cos-pi-4, name: Cosine of π/4, pattern: =pi 4 / cos, output: 2 sqrt 2 /, tags: [value], explain: \"cos(π/4) = √2/2.\" }\n  - { id: cos-pi-3, name: Cosine of π/3, pattern: =pi 3 / cos, output: 1 2 /, tags: [value], explain: \"cos(π/3) = 1/2.\" }\n  - { id: cos-pi-2, name: Cosine of π/2, pattern: =pi 2 / cos, output: \"0\", tags: [value], explain: \"cos(π/2) = 0.\" }\n  - { id: cos-pi, name: Cosine of π, pattern: =pi cos, output: \"-1\", tags: [value], explain: \"cos π = -1.\" }\n  - { id: tan-0, name: Tangent of 0, pattern: 0 tan, output: \"0\", tags: [value], explain: \"tan 0 = 0.\" }\n  - { id: tan-pi-6, name: Tangent of π/6, pattern: =pi 6 / tan, output: 3 sqrt 3 /, tags: [value], explain: \"tan(π/6) = √3/3.\" }\n  - { id: tan-pi-4, name: Tangent of π/4, pattern: =pi 4 / tan, output: \"1\", tags: [value], explain: \"tan(π/4) = 1.\" }\n  - { id: tan-pi-3, name: Tangent of π/3, pattern: =pi 3 / tan, output: 3 sqrt, tags: [value], explain: \"tan(π/3) = √3.\" }\n  - { id: arcsin-0, name: Arcsine of 0, pattern: 0 arcsin, output: \"0\", tags: [value], explain: \"sin 0 = 0, so arcsin 0 = 0.\" }\n  - { id: arcsin-half, name: Arcsine of 1/2, pattern: 1 2 / arcsin, output: =pi 6 /, tags: [value], explain: \"sin(π/6) = 1/2, so arcsin(1/2) = π/6.\" }\n  - { id: arcsin-1, name: Arcsine of 1, pattern: 1 arcsin, output: =pi 2 /, tags: [value], explain: \"sin(π/2) = 1, so arcsin 1 = π/2.\" }\n  - { id: arccos-0, name: Arccosine of 0, pattern: 0 arccos, output: =pi 2 /, tags: [value], explain: \"cos(π/2) = 0, so arccos 0 = π/2.\" }\n  - { id: arccos-half, name: Arccosine of 1/2, pattern: 1 2 / arccos, output: =pi 3 /, tags: [value], explain: \"cos(π/3) = 1/2, so arccos(1/2) = π/3.\" }\n  - { id: arccos-1, name: Arccosine of 1, pattern: 1 arccos, output: \"0\", tags: [value], explain: \"cos 0 = 1, so arccos 1 = 0.\" }\n  - { id: arccos-minus-1, name: Arccosine of -1, pattern: -1 arccos, output: =pi, tags: [value], explain: \"cos π = -1, so arccos(-1) = π.\" }\n  - { id: arctan-0, name: Arctangent of 0, pattern: 0 arctan, output: \"0\", tags: [value], explain: \"tan 0 = 0, so arctan 0 = 0.\" }\n  - { id: arctan-1, name: Arctangent of 1, pattern: 1 arctan, output: =pi 4 /, tags: [value], explain: \"tan(π/4) = 1, so arctan 1 = π/4.\" }\n  - { id: sinh-0, name: sinh of 0, pattern: 0 sinh, output: \"0\", tags: [value], explain: \"sinh 0 = 0.\" }\n  - { id: cosh-0, name: cosh of 0, pattern: 0 cosh, output: \"1\", tags: [value], explain: \"cosh 0 = 1.\" }\n  - { id: tanh-0, name: tanh of 0, pattern: 0 tanh, output: \"0\", tags: [value], explain: \"tanh 0 = 0.\" }\n\n  - { id: arctan-sqrt3, name: Arctangent of √3, pattern: 3 sqrt arctan, output: =pi 3 /, tags: [value], explain: \"tan(π/3) = √3, so arctan √3 = π/3.\" }\n  - { id: arctan-sqrt3-over-3, name: Arctangent of √3/3, pattern: 3 sqrt 3 / arctan, output: =pi 6 /, tags: [value], explain: \"tan(π/6) = √3/3, so arctan(√3/3) = π/6.\" }\n\n  # atan2(y, x): the angle of the point (x, y), in (-π, π]\n  - id: atan2-right\n    name: The angle of a point to the right\n    pattern: y x atan2\n    when:\n      x: [isPositiveConstant]\n    output: y x / arctan\n    explain: \"For x > 0, atan2(y, x) = arctan(y/x).\"\n    tags: [value]\n  - id: atan2-left-up\n    name: The angle of a point to the left\n    pattern: y x atan2\n    when:\n      x: [isNegativeConstant]\n      y: [isPositiveConstant]\n    output: y x / arctan =pi +\n    explain: \"For x < 0 and y > 0, atan2(y, x) = arctan(y/x) + π.\"\n    tags: [value]\n  - id: atan2-left-down\n    name: The angle of a point to the left\n    pattern: y x atan2\n    when:\n      x: [isNegativeConstant]\n      y: [isNegativeConstant]\n    output: y x / arctan =pi -\n    explain: \"For x < 0 and y < 0, atan2(y, x) = arctan(y/x) - π.\"\n    tags: [value]\n  - { id: atan2-negative-axis, name: The angle of a point on the negative axis, pattern: 0 x atan2, when: { x: [isNegativeConstant] }, output: =pi, tags: [value], explain: \"A point on the negative x-axis is at angle π.\" }\n  - { id: atan2-up, name: Straight up, pattern: y 0 atan2, when: { y: [isPositiveConstant] }, output: =pi 2 /, tags: [value], explain: \"A point straight up is at angle π/2.\" }\n  - { id: atan2-down, name: Straight down, pattern: y 0 atan2, when: { y: [isNegativeConstant] }, output: =pi 2 / neg, tags: [value], explain: \"A point straight down is at angle -π/2.\" }\n\n  # the odd inverses take the sign out; arccos(-u) = π - arccos u\n  - id: arcsin-odd\n    name: Arcsine of a negative\n    pattern: u arcsin\n    when:\n      u: [hasMinusSign]\n    output: u neg arcsin neg\n    explain: \"arcsin(-x) = -arcsin x.\"\n    tags: [symmetry]\n\n  - id: arctan-odd\n    name: Arctangent of a negative\n    pattern: u arctan\n    when:\n      u: [hasMinusSign]\n    output: u neg arctan neg\n    explain: \"arctan(-x) = -arctan x.\"\n    tags: [symmetry]\n\n  - id: arccos-negative\n    name: Arccosine of a negative\n    pattern: u arccos\n    when:\n      u: [hasMinusSign]\n    output: =pi u neg arccos -\n    explain: \"arccos(-x) = π - arccos x.\"\n    tags: [symmetry]\n\n  # ---- trigonometry: identities --------------------------------------------\n  - id: pythagorean\n    name: sin² + cos² = 1\n    pattern: u sin 2 ^ u cos 2 ^ +\n    commutative: true\n    output: \"1\"\n    explain: \"sin²{u} + cos²{u} = 1 for every angle.\"\n    tags: [identity]\n\n  - id: pythagorean-multiple\n    name: sin² + cos² = 1\n    pattern: a u sin 2 ^ * a u cos 2 ^ * +\n    commutative: true\n    output: a\n    explain: \"{a}·sin²{u} + {a}·cos²{u} = {a}(sin²{u} + cos²{u}) = {a}.\"\n    tags: [identity]\n\n  - id: one-minus-sin-squared\n    name: 1 - sin² = cos²\n    pattern: u sin 2 ^ neg 1 +\n    output: u cos 2 ^\n    explain: \"1 - sin²{u} = cos²{u}.\"\n    tags: [identity]\n\n  - id: one-minus-cos-squared\n    name: 1 - cos² = sin²\n    pattern: u cos 2 ^ neg 1 +\n    output: u sin 2 ^\n    explain: \"1 - cos²{u} = sin²{u}.\"\n    tags: [identity]\n\n  - id: sin-over-cos\n    name: sin/cos is tan\n    pattern: u sin u cos /\n    output: u tan\n    explain: \"sin {u} / cos {u} = tan {u}.\"\n    tags: [identity]\n\n  - id: cos-over-sin\n    name: cos/sin is cot\n    pattern: u cos u sin /\n    output: u cot\n    explain: \"cos {u} / sin {u} = cot {u}.\"\n    tags: [identity]\n\n  - id: sin-arcsin\n    name: sin undoes arcsin\n    pattern: u arcsin sin\n    output: u\n    explain: \"sin(arcsin {u}) = {u}.\"\n    tags: [inverse]\n\n  - id: cos-arccos\n    name: cos undoes arccos\n    pattern: u arccos cos\n    output: u\n    explain: \"cos(arccos {u}) = {u}.\"\n    tags: [inverse]\n\n  - id: tan-arctan\n    name: tan undoes arctan\n    pattern: u arctan tan\n    output: u\n    explain: \"tan(arctan {u}) = {u}.\"\n    tags: [inverse]\n\n  - id: cosh-squared-minus-sinh-squared\n    name: cosh² - sinh² = 1\n    pattern: u cosh 2 ^ u sinh 2 ^ -\n    output: \"1\"\n    explain: \"cosh²{u} - sinh²{u} = 1.\"\n    tags: [identity]\n\n  # ---- logs: opt-in rewrites (run with cas.rewrite(x, 'expand-log') or 'combine-log') ----\n  - id: ln-product\n    name: Log of a product\n    mode: expand-log\n    pattern: a b * ln\n    output: a ln b ln +\n    explain: \"ln({a}·{b}) = ln {a} + ln {b} (for positive {a}, {b}).\"\n    tags: [log]\n\n  - id: ln-quotient\n    name: Log of a quotient\n    mode: expand-log\n    pattern: a b / ln\n    output: a ln b ln -\n    explain: \"ln({a}/{b}) = ln {a} - ln {b} (for positive {a}, {b}).\"\n    tags: [log]\n\n  - id: ln-power\n    name: Log of a power\n    mode: expand-log\n    pattern: a n ^ ln\n    output: n a ln *\n    explain: \"ln({a}^{n}) = {n}·ln {a} (for positive {a}).\"\n    tags: [log]\n\n  - id: ln-root\n    name: Log of a square root\n    mode: expand-log\n    pattern: a sqrt ln\n    output: a ln 2 /\n    explain: \"ln √{a} = ½ ln {a}.\"\n    tags: [log]\n\n  - id: ln-sum-combine\n    name: Sum of logs\n    mode: combine-log\n    pattern: a ln b ln +\n    commutative: true\n    output: a b * ln\n    explain: \"ln {a} + ln {b} = ln({a}·{b}).\"\n    tags: [log]\n\n  - id: ln-difference-combine\n    name: Difference of logs\n    mode: combine-log\n    pattern: a ln b ln -\n    output: a b / ln\n    explain: \"ln {a} - ln {b} = ln({a}/{b}).\"\n    tags: [log]\n\n  - id: ln-multiple-combine\n    name: A multiple of a log\n    mode: combine-log\n    pattern: n a ln *\n    when:\n      n: [isRational]\n    output: a n ^ ln\n    explain: \"{n}·ln {a} = ln({a}^{n}).\"\n    tags: [log]\n",
  // rules/cas/solve.yaml
  "name: Solving by undoing\n\n# mode: isolate. Each rule undoes the outermost function on the side with the\n# unknown: ln u = r → u = e^r. The predicates hasVariable and freeOfVariable mean\n# \"mentions / doesn't mention the unknown being solved for\".\n#\n# The CAS does the rest itself: it moves terms without the unknown to the other\n# side, divides by a coefficient, and when the unknown appears in several places\n# it uses the polynomial methods (factoring, the quadratic formula) or splits a\n# product equal to 0. Every answer is checked in the original equation, so a\n# rule may give extra candidates (squaring both sides does): the wrong ones are\n# dropped, with a step saying so.\n#\n# An output can give several answers: `pm` (±) splits into two, and so does\n# `|` (or): \"u r arcsin = u =pi r arcsin - = |\".\n\nrules:\n  - id: iso-swap\n    name: Unknown on the left\n    mode: isolate\n    pattern: l r =\n    when:\n      l: [freeOfVariable]\n      r: [hasVariable]\n    output: r l =\n    priority: 20\n    explain: \"Swap the sides so the unknown is on the left.\"\n    tags: [tidy]\n\n  - id: iso-ln\n    name: Undo the log\n    mode: isolate\n    pattern: u ln r =\n    when:\n      u: [hasVariable]\n    output: u =e r ^ =\n    explain: \"Raise e to each side: e^(ln {u}) = {u}.\"\n    tags: [inverse]\n\n  - id: iso-log\n    name: Undo the log\n    mode: isolate\n    pattern: b u log r =\n    when:\n      u: [hasVariable]\n      b: [freeOfVariable]\n    output: u b r ^ =\n    explain: \"Raise {b} to each side: {b}^(log base {b} of {u}) = {u}.\"\n    tags: [inverse]\n\n  - id: iso-exp\n    name: Undo e to a power\n    mode: isolate\n    pattern: =e u ^ r =\n    when:\n      u: [hasVariable]\n    output: u r ln =\n    explain: \"Take ln of each side: ln(e^{u}) = {u}.\"\n    tags: [inverse]\n\n  - id: iso-exponential\n    name: Undo a power of a number\n    mode: isolate\n    pattern: b u ^ r =\n    when:\n      u: [hasVariable]\n      b: [freeOfVariable]\n    output: u b r log =\n    explain: \"Take the log to base {b} of each side.\"\n    tags: [inverse]\n\n  - id: iso-square\n    name: Undo the square\n    mode: isolate\n    pattern: u 2 ^ r =\n    when:\n      u: [hasVariable]\n    output: u r sqrt pm =\n    priority: 1\n    explain: \"Take the square root of each side; {u} can be positive or negative.\"\n    tags: [inverse]\n\n  - id: iso-even-power\n    name: Undo an even power\n    mode: isolate\n    pattern: u n ^ r =\n    when:\n      u: [hasVariable]\n      n: [isEvenWhole]\n    output: u r 1 n / ^ pm =\n    explain: \"Take the root of each side (the {n}th root); {u} can be positive or negative.\"\n    tags: [inverse]\n\n  - id: iso-odd-power\n    name: Undo an odd power\n    mode: isolate\n    pattern: u n ^ r =\n    when:\n      u: [hasVariable]\n      n: [isOddWhole]\n    output: u r 1 n / ^ =\n    explain: \"Take the root of each side (the {n}th root).\"\n    tags: [inverse]\n\n  - id: iso-fractional-power\n    name: Undo a power\n    mode: isolate\n    pattern: u n ^ r =\n    when:\n      u: [hasVariable]\n      n: [isRational]\n    output: u r 1 n / ^ =\n    priority: -1\n    explain: \"Raise each side to the power 1/{n}.\"\n    tags: [inverse]\n\n  - id: iso-sqrt\n    name: Undo the square root\n    mode: isolate\n    pattern: u sqrt r =\n    when:\n      u: [hasVariable]\n    output: u r 2 ^ =\n    explain: \"Square each side (this can add answers, so each one is checked at the end).\"\n    tags: [inverse]\n\n  - id: iso-root\n    name: Undo the root\n    mode: isolate\n    pattern: n u root r =\n    when:\n      u: [hasVariable]\n      n: [freeOfVariable]\n    output: u r n ^ =\n    explain: \"Raise each side to the power {n}.\"\n    tags: [inverse]\n\n  - id: iso-reciprocal\n    name: Undo the fraction\n    mode: isolate\n    pattern: c u / r =\n    when:\n      u: [hasVariable]\n      c: [freeOfVariable]\n    output: u c r / =\n    explain: \"{c}/{u} = {r}, so {u} = {c}/{r}.\"\n    tags: [inverse]\n\n  - id: iso-abs\n    name: Undo the absolute value\n    mode: isolate\n    pattern: u abs r =\n    when:\n      u: [hasVariable]\n    output: u r pm =\n    explain: \"|{u}| = {r} means {u} is {r} or -{r}.\"\n    tags: [inverse]\n\n  - id: iso-sin\n    name: Undo the sine\n    mode: isolate\n    pattern: u sin r =\n    when:\n      u: [hasVariable]\n    output: u r arcsin = u =pi r arcsin - = |\n    explain: \"Two angles in a turn have sine {r}: arcsin {r} and π - arcsin {r} (add any whole number of turns, 2πk, for the rest).\"\n    tags: [inverse, trig]\n\n  - id: iso-cos\n    name: Undo the cosine\n    mode: isolate\n    pattern: u cos r =\n    when:\n      u: [hasVariable]\n    output: u r arccos pm =\n    explain: \"Two angles in a turn have cosine {r}: ±arccos {r} (add 2πk for the rest).\"\n    tags: [inverse, trig]\n\n  - id: iso-tan\n    name: Undo the tangent\n    mode: isolate\n    pattern: u tan r =\n    when:\n      u: [hasVariable]\n    output: u r arctan =\n    explain: \"Take arctan of each side (add πk for the rest).\"\n    tags: [inverse, trig]\n\n  - { id: iso-arcsin, name: Undo arcsin, mode: isolate, pattern: u arcsin r =, when: { u: [hasVariable] }, output: u r sin =, tags: [inverse], explain: \"Take sin of each side.\" }\n  - { id: iso-arccos, name: Undo arccos, mode: isolate, pattern: u arccos r =, when: { u: [hasVariable] }, output: u r cos =, tags: [inverse], explain: \"Take cos of each side.\" }\n  - { id: iso-arctan, name: Undo arctan, mode: isolate, pattern: u arctan r =, when: { u: [hasVariable] }, output: u r tan =, tags: [inverse], explain: \"Take tan of each side.\" }\n  - { id: iso-sinh, name: Undo sinh, mode: isolate, pattern: u sinh r =, when: { u: [hasVariable] }, output: u r arcsinh =, tags: [inverse], explain: \"Take arcsinh of each side.\" }\n  - { id: iso-tanh, name: Undo tanh, mode: isolate, pattern: u tanh r =, when: { u: [hasVariable] }, output: u r arctanh =, tags: [inverse], explain: \"Take arctanh of each side.\" }\n  - { id: iso-cosh, name: Undo cosh, mode: isolate, pattern: u cosh r =, when: { u: [hasVariable] }, output: u r arccosh pm =, tags: [inverse], explain: \"Two numbers have cosh {r}: ±arccosh {r}.\" }\n  - { id: iso-arcsinh, name: Undo arcsinh, mode: isolate, pattern: u arcsinh r =, when: { u: [hasVariable] }, output: u r sinh =, tags: [inverse], explain: \"Take sinh of each side.\" }\n  - { id: iso-arccosh, name: Undo arccosh, mode: isolate, pattern: u arccosh r =, when: { u: [hasVariable] }, output: u r cosh =, tags: [inverse], explain: \"Take cosh of each side.\" }\n  - { id: iso-arctanh, name: Undo arctanh, mode: isolate, pattern: u arctanh r =, when: { u: [hasVariable] }, output: u r tanh =, tags: [inverse], explain: \"Take tanh of each side.\" }\n",
];

// added by createCAS({ complex: true })
export const COMPLEX_RULES = [
  // rules/cas/complex/complex.yaml
  "name: Complex numbers\n\n# Loaded only by createCAS({ complex: true }), where i is the imaginary unit.\n# The arithmetic (i² = -1, √-4 = 2i, (2 + 3i)(1 - i) = 5 + i, 1/(1 + i) = (1 - i)/2)\n# and Re, Im, conj, arg, |z| are the normal form's (src/cas/form.js); unknowns\n# count as real, so Re(x + 3i) = x. Write a complex unknown as a + bi.\n\noperators:\n  - { symbol: re, arity: 1, label: real part }\n  - { symbol: im, arity: 1, label: imaginary part }\n  - { symbol: conj, arity: 1, label: complex conjugate }\n  - { symbol: arg, arity: 1, label: argument }\n\nrules:\n  - id: euler\n    name: Euler's formula\n    pattern: =e u ^\n    when:\n      u: [hasImaginaryPart, isConstant]\n    output: =e u re ^ u im cos =i u im sin * + *\n    explain: \"e^(a + bi) = e^a (cos b + i sin b).\"\n    tags: [complex]\n\n  - id: ln-negative\n    name: Log of a negative number\n    pattern: u ln\n    when:\n      u: [isNegativeConstant]\n    output: u neg ln =i =pi * +\n    explain: \"{u} = |{u}|·e^(iπ), so ln {u} = ln |{u}| + iπ (the principal value).\"\n    tags: [complex]\n\n  - id: ln-complex\n    name: Log of a complex number\n    pattern: u ln\n    when:\n      u: [hasImaginaryPart, isConstant]\n    output: u abs ln u arg =i * +\n    explain: \"ln z = ln |z| + i arg z (the principal value).\"\n    tags: [complex]\n\n  - id: i-to-the-i\n    name: i to the power i\n    pattern: =i =i ^\n    output: =e =pi 2 / neg ^\n    explain: \"i = e^(iπ/2), so i^i = e^(i·iπ/2) = e^(-π/2) (the principal value).\"\n    tags: [complex]\n",
];
